class Solution {
public:
    vector<int> distinctDifferenceArray(vector<int>& nums) {
        int n = nums.size();
        vector<int> ans;
        for (int i = 0; i < n; i++) {
            set<int> p(nums.begin(), nums.begin() + i + 1);
            set<int> s(nums.begin() + i + 1, nums.end());
            ans.push_back((int)p.size() - (int)s.size());
        }
        return ans;
    }
};

