class Solution {
public:
    vector<int> distinctDifferenceArray(vector<int>& nums) {
        int n = nums.size(), d = 0;
        unordered_map<int,int> cnt;
        vector<int> suf(n + 1, 0);
        for (int i = n - 1; i >= 0; i--) {
            if (cnt[nums[i]]++ == 0) d++;
            suf[i] = d;
        }
        cnt.clear(); d = 0;
        vector<int> ans;
        for (int i = 0; i < n; i++) {
            if (cnt[nums[i]]++ == 0) d++;
            ans.push_back(d - suf[i + 1]);
        }
        return ans;
    }
};

