class Solution {
    public int[] distinctDifferenceArray(int[] nums) {
        int n = nums.length, d = 0;
        Map<Integer,Integer> cnt = new HashMap<>();
        int[] suf = new int[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            cnt.merge(nums[i], 1, Integer::sum);
            if (cnt.get(nums[i]) == 1) d++;
            suf[i] = d;
        }
        cnt.clear(); d = 0;
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            cnt.merge(nums[i], 1, Integer::sum);
            if (cnt.get(nums[i]) == 1) d++;
            ans[i] = d - suf[i + 1];
        }
        return ans;
    }
}

