    const cnt = new Map();
    const suf = new Array(n + 1).fill(0);
    let d = 0;
    for (let i = n - 1; i >= 0; i--) {
        cnt.set(nums[i], (cnt.get(nums[i]) || 0) + 1);
        if (cnt.get(nums[i]) === 1) d++;
        suf[i] = d;
    }
    cnt.clear(); d = 0;
    const ans = [];
    for (let i = 0; i < n; i++) {
        cnt.set(nums[i], (cnt.get(nums[i]) || 0) + 1);
        if (cnt.get(nums[i]) === 1) d++;
        ans.push(d - suf[i + 1]);
    }
    return ans;
};
